89	// record does not declare — into the workspace's system host. The declared
90	// baseline is the host record's stored values, never a re-scan, so a
91	// component whose scaffold disappeared stays declared. The record is
92	// rewritten last, after every declaration file landed, and never on a
93	// conflict, so a failed update retries against an honest baseline.
94	func Update(ctx context.Context, opts UpdateOptions) error {
95		opts.applyDefaults()
96	
97		plan, err := planUpdate(opts)
98		if err != nil {
99			return err
100		}
101		if len(plan.orphans) == 0 {
102			fmt.Fprintln(opts.Stderr, ErrNoOrphans.Error())
103			return nil
104		}
105		for _, appID := range plan.kept {
106			fmt.Fprintf(opts.Stderr, "note: component %s declared but no scaffold found — kept as declared\n", appID)
107		}
108	
109		// The payload and the record rewrite both start from the record's own
110		// values, so hand-recorded keys survive the round-trip untouched.
111		merged := make(map[string]any, len(plan.baseline))
112		for k, v := range plan.baseline {
113			merged[k] = v
114		}
115		mergedComponents, err := mergedComponentEntries(plan)
116		if err != nil {
117			return err
118		}
119		merged["components"] = mergedComponents
120		if err := mergeWiring(plan, merged); err != nil {
121			return err
122		}
123	
124		names := make([]string, len(plan.orphans))
125		for i, c := range plan.orphans {
126			names[i] = c.AppID
127		}
128		fmt.Fprintf(opts.Stderr, "updating %s: adding components %s\n", plan.hostDir, strings.Join(names, ", "))
129	
130		// The fetch resolves once against the merged payload; the baseline and
131		// override payloads re-resolve against the same extracted library, so a
132		// template override fetches what it renders and one download serves
133		// all three resolutions.
134		prep, err := template.PrepareCreate(ctx, template.CreateOptions{
135			Template:      orDefault(opts.Template, plan.hostRec.Template),
136			Version:       orDefault(opts.Version, plan.hostRec.Version),
137			SetValues:     merged,
138			NoInput:       true,
139			OnManifest:    requireFactsPayload,
140			Stdin:         strings.NewReader(""),
141			Stdout:        opts.Stdout,
142			Stderr:        opts.Stderr,
143			HTTP:          opts.HTTP,
144			UserAgent:     opts.UserAgent,
145			Owner:         orDefault(opts.Owner, plan.hostRec.Owner),
146			Repo:          orDefault(opts.Repo, plan.hostRec.Repo),
147			GitHubBaseURL: opts.GitHubBaseURL,
148		})
149		if err != nil {
150			return err
151		}
152		defer prep.Cleanup()
153	
154		// The baseline is what the host was last rendered from; the render
155		// decides per file whether a difference is the update itself (safe to
156		// write) or a genuine divergence (a conflict). A template override
157		// invalidates the baseline, so the strict comparison applies instead.
158		var baseline map[string]any
159		if opts.Template == "" && opts.Version == "" && (opts.Owner == "" || opts.Owner == plan.hostRec.Owner) && (opts.Repo == "" || opts.Repo == plan.hostRec.Repo) {
160			baseline, err = template.Resolve(prep.Manifest, nil, strings.NewReader(""), plan.baseline, nil)
